const U1: u64 = 0x38;
const U2: u64 = 0x40;
const U3E: u64 = 0x16c;
const W1: u64 = 0xf0;
const DATA: u64 = 0x188;
const FAIL: u64 = 0x174;
const DONE: u64 = 0x104;

const BASE: u64 = 0x8000_0000;
const ROOT: u64 = 0x8001_0000;
const GIG: u64 = 0x4000_0000;
const PTE_USER: u64 = (0x80000 << 10) | 0x1f; // V R W X U, A and D clear
const PTE_SUPER: u64 = (0x80000 << 10) | 0x0f; // V R W X, A and D clear

#[test]
fn leader_csr_and_privileged_words_match_llvm() {
    assert!(CASES.len() > 150);
    for (asm, word, inst) in CASES {
        assert_eq!(decode(*word), Some(*inst), "decode {word:#010x} ({asm})");
        assert_eq!(encode(*inst), *word, "encode {inst:?} ({asm})");
    }
}

fn reg(cpu: &Cpu, name: &str, idx: usize) -> u64 {
    let v = cpu.x[idx];
    eprintln!("{name:>4} = {v:#x}");
    v
}

#[test]
fn leader_llvm_privilege_program_on_tick() {
    let mut ram = Ram::new(BASE, 0x2_0000);
    ram.load(BASE, PROGRAM).unwrap();
    ram.write(ROOT + 8, 8, PTE_USER).unwrap(); // VA 0x4000_0000 -> PA 0x8000_0000, user
    ram.write(ROOT + 16, 8, PTE_SUPER).unwrap(); // VA 0x8000_0000 -> PA 0x8000_0000, supervisor
    let mut cpu = Cpu::new(BASE);
    assert_eq!(cpu.mode, Mode::Machine);

    let mut traps = Vec::new();
    let mut steps = 0;
    loop {
        steps += 1;
        assert!(steps < 2000, "program did not reach wfi");
        match cpu.tick(&mut ram) {
            Step::Retired => {}
            Step::Exception(t) => traps.push(t),
            Step::Interrupt(c) => panic!("unexpected interrupt {c}"),
            Step::Wfi => break,
        }
    }
    let va_data = BASE + DATA - GIG;
    assert_eq!(
        traps,
        [
            Trap::Ecall,
            Trap::Ecall,
            Trap::Ecall,
            Trap::Ecall,
            Trap::LoadPageFault(va_data)
        ]
    );
    assert_eq!(cpu.pc, BASE + W1 + 4, "wfi must retire with pc advanced");
    assert_eq!(cpu.mode, Mode::Machine);

    // Nothing pending: wfi again would just retire; raise the machine timer instead.
    cpu.set_pending(7, true);
    assert_eq!(cpu.tick(&mut ram), Step::Interrupt(7));
    cpu.set_pending(7, false);
    loop {
        steps += 1;
        assert!(steps < 4000, "handler did not reach the final wfi");
        match cpu.tick(&mut ram) {
            Step::Retired => {}
            Step::Wfi => break,
            other => panic!("unexpected {other:?} after the interrupt"),
        }
    }
    eprintln!("{steps} ticks");
    assert_ne!(reg(&cpu, "a0", 10), 0xbad, "program took its fail path");
    assert_eq!(cpu.pc, BASE + DONE + 4);
    assert_eq!(reg(&cpu, "s0", 8), 6, "trap count");
    assert_eq!(reg(&cpu, "s1", 9), 8, "U ecall to M: mcause");
    assert_eq!(reg(&cpu, "s2", 18), BASE + U1, "U ecall to M: mepc");
    assert_eq!(reg(&cpu, "s3", 19), 8, "delegated U ecall: scause");
    assert_eq!(reg(&cpu, "s4", 20), BASE + U2, "delegated U ecall: sepc");
    assert_eq!(reg(&cpu, "s5", 21) & 0x100, 0, "SPP after a trap from U");
    assert_eq!(reg(&cpu, "s6", 22), 9, "S ecall to M: mcause");
    assert_eq!(reg(&cpu, "s7", 23), 1, "MPP after a trap from S");
    assert_eq!(reg(&cpu, "s8", 24), 8, "paged U ecall: scause");
    assert_eq!(
        reg(&cpu, "s9", 25),
        BASE + U3E - GIG,
        "paged U ecall: sepc is virtual"
    );
    assert_eq!(reg(&cpu, "s10", 26), 13, "S load of a U page without SUM");
    assert_eq!(
        reg(&cpu, "s11", 27),
        va_data,
        "mtval is the virtual address"
    );
    assert_eq!(
        reg(&cpu, "a1", 11),
        0x1122_3344_5566_7788,
        "load through Sv39"
    );
    assert_eq!(
        ram.read(BASE + DATA + 8, 8).unwrap(),
        77,
        "store through Sv39"
    );
    assert_eq!(reg(&cpu, "a4", 14), (1 << 63) | 7, "timer interrupt mcause");
    assert_eq!(reg(&cpu, "a5", 15), BASE + W1 + 4, "mepc after wfi");
    assert_eq!(cpu.csr_read(0x342), Some((1 << 63) | 7));

    let user = ram.read(ROOT + 8, 8).unwrap();
    let sup = ram.read(ROOT + 16, 8).unwrap();
    assert_eq!(user, PTE_USER | 0xc0, "user page: A and D set by the walk");
    assert_eq!(
        sup,
        PTE_SUPER | 0x40,
        "supervisor page: A set, D clear (no stores)"
    );
}

#[test]
fn leader_program_fails_cleanly_without_page_tables() {
    // No PTEs: the first user fetch after satp is set is an instruction page fault to M, which
    // the handler does not expect, so the program must end in its fail path; never a panic.
    let mut ram = Ram::new(BASE, 0x2_0000);
    ram.load(BASE, PROGRAM).unwrap();
    let mut cpu = Cpu::new(BASE);
    let mut faults = Vec::new();
    for _ in 0..2000 {
        match cpu.tick(&mut ram) {
            Step::Exception(t) => faults.push(t),
            Step::Wfi => break,
            _ => {}
        }
    }
    assert_eq!(
        faults.last(),
        Some(&Trap::InstPageFault(BASE + 0x158 - GIG))
    );
    assert_eq!(cpu.x[10], 0xbad);
    assert_eq!(cpu.pc, BASE + FAIL + 12);
}
